"""
Test script for Brain Tumor Analysis API
Tests all endpoints to ensure they work correctly
"""

import requests
import json
import os
import sys

# API Configuration
BASE_URL = 'http://localhost:5000'
API_KEY = None  # Will be set when API starts

def test_health_check():
    """Test health check endpoint"""
    print("Testing health check...")
    try:
        response = requests.get(f'{BASE_URL}/health')
        if response.status_code == 200:
            print("✓ Health check passed")
            return True
        else:
            print(f"✗ Health check failed: {response.status_code}")
            return False
    except Exception as e:
        print(f"✗ Health check error: {e}")
        return False

def test_generate_api_key():
    """Test API key generation"""
    print("Testing API key generation...")
    try:
        response = requests.post(f'{BASE_URL}/generate-api-key')
        if response.status_code == 200:
            result = response.json()
            global API_KEY
            API_KEY = result.get('api_key')
            print(f"✓ API key generated: {API_KEY[:20]}...")
            return True
        else:
            print(f"✗ API key generation failed: {response.status_code}")
            return False
    except Exception as e:
        print(f"✗ API key generation error: {e}")
        return False

